<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\OAuth\Client\Application\ClientAuthenticator;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientAuthPolicy;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientCredentials;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Application\AccessTokenPolicy;
use OpenApi\Attributes as OA;

/**
 * REST controller that implements the OAuth 2.0 Token Introspection endpoint (RFC 7662).
 *
 * This controller exposes a POST endpoint at /oauth/openid/{tenant}/introspect that allows
 * resource servers to query whether a given access token is currently active. The
 * caller must authenticate as a registered confidential client through ClientAuthenticator: with
 * its secret (HTTP Basic or client_id and client_secret in the body) or, when registered for
 * private_key_jwt, with a client assertion.
 *
 * The token is judged by AccessTokenPolicy, the same verifier as UserInfo and the bearer
 * middleware: when it is an access token of this tenant and issuer, unexpired and not revoked,
 * the endpoint returns a JSON object with active=true and a set of standard JWT claims extracted
 * from the token payload (sub, scope, exp, iss, etc.). Otherwise (invalid, expired, revoked, of
 * another tenant, or an ID or refresh token) only {"active": false} is returned — no additional
 * information is disclosed to avoid leaking token metadata.
 *
 * Relationships: depends on AccessTokenPolicy for verification and ClientAuthenticator for client
 * authentication.
 */
class IntrospectionController
{
    public function __construct(
        private readonly AccessTokenPolicy $policy,
        private readonly ClientAuthenticator $clients,
        private readonly Context $context,
    ) {
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/introspect',
        summary: 'Token Introspection (RFC 7662)',
        description: 'Returns metadata about an access token; ID, refresh, revoked and foreign tokens are inactive. Requires client authentication via HTTP Basic, client_id/client_secret in the body or a private_key_jwt client assertion.',
        tags: ['OIDC'],
        security: [['basicAuth' => []]],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        requestBody: new OA\RequestBody(
            required: true,
            content: new OA\MediaType(
                mediaType: 'application/x-www-form-urlencoded',
                schema: new OA\Schema(properties: [
                    new OA\Property(property: 'token', type: 'string', description: 'Token to introspect'),
                    new OA\Property(property: 'token_type_hint', type: 'string', description: 'access_token (other token types are inactive)'),
                    new OA\Property(property: 'client_id', type: 'string'),
                    new OA\Property(property: 'client_secret', type: 'string'),
                    new OA\Property(property: 'client_assertion_type', type: 'string', example: ClientCredentials::ASSERTION_TYPE),
                    new OA\Property(property: 'client_assertion', type: 'string', description: 'private_key_jwt client assertion (RFC 7523)'),
                ])
            )
        ),
        responses: [
            new OA\Response(
                response: 200,
                description: 'Introspection response',
                content: new OA\JsonContent(properties: [
                    new OA\Property(property: 'active', type: 'boolean'),
                    new OA\Property(property: 'scope', type: 'string'),
                    new OA\Property(property: 'client_id', type: 'string'),
                    new OA\Property(property: 'token_type', type: 'string'),
                    new OA\Property(property: 'exp', type: 'integer'),
                    new OA\Property(property: 'sub', type: 'string'),
                    new OA\Property(property: 'iss', type: 'string'),
                    new OA\Property(property: 'jti', type: 'string'),
                    new OA\Property(property: 'tenant', type: 'string'),
                ])
            ),
            new OA\Response(response: 400, description: 'Missing token parameter'),
            new OA\Response(response: 401, description: 'Client authentication failed'),
        ]
    )]
    /**
     * Handles the token introspection POST request and returns the token metadata or an inactive response.
     *
     * Authenticates the calling client, applies AccessTokenPolicy for the tenant, and returns
     * either the full claims payload or {"active": false}.
     */
    public function post(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $params = (array) ($request->getParsedBody() ?? []);
        $token = (string) ($params['token'] ?? '');
        if ($token === '') {
            return $this->jsonError(
                $response,
                400,
                'invalid_request',
                'missing token parameter'
            );
        }

        $tenant = (string) ($args['tenant'] ?? '');
        $issuer = $this->context->getIssuer($tenant);
        $credentials = ClientCredentials::fromHttp($request->getHeaderLine('Authorization'), $request->getServerParams(), $params);
        if ($this->clients->authenticate($tenant, $credentials, ClientAuthPolicy::Secret, $issuer, "{$issuer}/introspect") === null) {
            return $this->jsonError(
                $response,
                401,
                'invalid_client',
                'client authentication failed'
            );
        }

        try {
            $payload = $this->policy->verify($tenant, $token);
        } catch (UnauthorizedException) {
            return $this->jsonResponse($response, ['active' => false]);
        }

        return $this->jsonResponse($response, $this->buildResponse($payload));
    }

    /** @param array<string, mixed> $payload */
    private function buildResponse(array $payload): array
    {
        $response = ['active' => true];

        $scope = $payload['scope'] ?? null;
        if (is_array($scope)) {
            $scope = implode(' ', $scope);
        }
        $this->setIfNotEmpty($response, 'scope', $scope);
        $this->setIfNotEmpty($response, 'client_id', $payload['azp'] ?? null);
        $this->setIfNotEmpty($response, 'token_type', $payload['typ'] ?? 'Bearer');
        $this->setIfNotEmpty($response, 'exp', $payload['exp'] ?? null);
        $this->setIfNotEmpty($response, 'iat', $payload['iat'] ?? null);
        $this->setIfNotEmpty($response, 'nbf', $payload['nbf'] ?? null);
        $this->setIfNotEmpty($response, 'sub', $payload['sub'] ?? null);
        $this->setIfNotEmpty($response, 'aud', $payload['aud'] ?? null);
        $this->setIfNotEmpty($response, 'iss', $payload['iss'] ?? null);
        $this->setIfNotEmpty($response, 'jti', $payload['jti'] ?? null);
        $this->setIfNotEmpty($response, 'tenant', $payload['tenant'] ?? null);
        $this->setIfNotEmpty($response, 'roles', $payload['roles'] ?? null);
        $this->setIfNotEmpty($response, 'groups', $payload['groups'] ?? null);
        $this->setIfNotEmpty($response, 'email', $payload['email'] ?? null);
        $this->setIfNotEmpty($response, 'name', $payload['name'] ?? null);

        return $response;
    }

    private function setIfNotEmpty(array &$payload, string $key, mixed $value): void
    {
        if ($value === null || $value === '') {
            return;
        }
        $payload[$key] = $value;
    }

    private function jsonError(ResponseInterface $response, int $status, string $error, string $description): ResponseInterface
    {
        $encoded = json_encode(['error' => $error, 'error_description' => $description]);
        $response->getBody()->write($encoded !== false ? $encoded : '{}');
        return $response->withStatus($status)->withHeader('Content-Type', 'application/json');
    }

    /** @param array<string, mixed> $payload */
    private function jsonResponse(ResponseInterface $response, array $payload): ResponseInterface
    {
        $encoded = json_encode($payload);
        $response->getBody()->write($encoded !== false ? $encoded : '{}');
        return $response->withHeader('Content-Type', 'application/json');
    }
}
